pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        // Fund the actor and give the contract some initial ether to allow withdrawals later
        vm.deal(actor, amount + 1 ether);
        vm.deal(address(c), 0);
        // Check the balance before deposit
        uint256 balanceBefore = actor.balance;
        // Perform deposit
        vm.prank(actor);
        try c.deposit{value: amount}() {
            // Deposit succeeded (assertion in reference passed, or no assertion in mutant)
            // After a successful deposit, the contract's balance must be at least the deposited amount.
            // In the reference, overflow is prevented, so amount is added to the user's internal balance.
            // In the mutant, overflow can occur, causing the user's internal balance to not reflect the full amount,
            // but the contract still holds the ether. We check that the contract's ether balance increased by at least amount.
            assertTrue(address(c).balance >= balanceBefore + amount);
        } catch {
            // Deposit reverted (reference assertion failed). This is only allowed for the reference.
            // Mutant never reverts here, so this path distinguishes them.
            assertTrue(false, "Deposit should succeed for all inputs");
        }
    }
}

